import{_ as t,o as s,c as i,ag as n}from"./chunks/framework.yGqRar0R.js";const g=JSON.parse('{"title":"API or connectivity","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting/api-or-connectivity.md","filePath":"guide/troubleshooting/api-or-connectivity.md"}'),o={name:"guide/troubleshooting/api-or-connectivity.md"};function a(r,e,l,h,c,p){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="api-or-connectivity" tabindex="-1">API or connectivity <a class="header-anchor" href="#api-or-connectivity" aria-label="Permalink to &quot;API or connectivity&quot;">​</a></h1><p>Problems reaching Protocube or the daemon, or mismatched HTTP/TLS between clients and servers, usually come down to URL schemes, API keys, TLS files, or network reachability. Below are <strong>common API-related errors</strong> and how to approach them.</p><h2 id="common-api-errors" tabindex="-1">Common API errors <a class="header-anchor" href="#common-api-errors" aria-label="Permalink to &quot;Common API errors&quot;">​</a></h2><h3 id="http-server-gave-http-response-to-https-client" tabindex="-1"><code>http: server gave HTTP response to HTTPS client</code> <a class="header-anchor" href="#http-server-gave-http-response-to-https-client" aria-label="Permalink to &quot;\`http: server gave HTTP response to HTTPS client\`&quot;">​</a></h3><p>The client is speaking <strong>HTTPS</strong> to an endpoint that is only serving <strong>plain HTTP</strong> (or the reverse: less often, you’ll see the opposite mismatch).</p><p><strong>What to do:</strong> Align the scheme in your config with what the service actually exposes.</p><ul><li>If the service uses <strong>HTTP</strong>, URLs must start with <code>http://</code>, not <code>https://</code>.</li><li>Examples: <ul><li>Protocube: <code>http://protocube.sls.net:5620</code></li><li>Daemon API: <code>http://daemon.sls.net:5585</code></li></ul></li></ul><p>Check the daemon <code>config.yml</code>. Ensure that the <strong>API URL</strong> and <strong>remote URL</strong> are correct so <strong>HTTP</strong> and <strong>HTTPS</strong> are set the right way for each endpoint.</p><h3 id="_401-unauthorized-invalid-api-key" tabindex="-1"><code>401 Unauthorized: invalid API key</code> <a class="header-anchor" href="#_401-unauthorized-invalid-api-key" aria-label="Permalink to &quot;\`401 Unauthorized: invalid API key\`&quot;">​</a></h3><p>The API key in your <strong>daemon</strong> <code>config.yml</code> does not match what Protocube expects (wrong key, revoked key, or wrong key <strong>type</strong>).</p><p><strong>What to do:</strong></p><ul><li>Generate a new key in Protocube and update the daemon config.</li><li>See <a href="./../installing-daemon.html#create-a-node-api-key">Create a node API key</a> for the full flow.</li><li>When creating a key for the daemon, make sure you create a <strong>node API key</strong>.</li></ul><h3 id="tls-no-certificates-configured-or-missing-cert-files" tabindex="-1"><code>tls: no certificates configured</code> (or missing cert files) <a class="header-anchor" href="#tls-no-certificates-configured-or-missing-cert-files" aria-label="Permalink to &quot;\`tls: no certificates configured\` (or missing cert files)&quot;">​</a></h3><p>TLS is enabled but <strong>no valid certificates</strong> are loaded, or the paths in config <strong>do not exist</strong> on the host.</p><p><strong>What to do:</strong></p><ul><li><strong>Preferred:</strong> Configure real certificates (for example <a href="https://letsencrypt.org/" target="_blank" rel="noreferrer">Let’s Encrypt</a>) and point config at the correct <code>cert</code> and <code>key</code> files.</li><li><strong>Or</strong> fix filesystem paths so the process can read the files you configured.</li><li><strong>Or</strong> use HTTP instead of HTTPS if you are testing locally or using a reverse proxy like Nginx that handles TLS termination.</li></ul><p>Example daemon API block with TLS:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://daemon.sls.net:5585</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0.0.0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5585</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/ssl/certs/sls.crt</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/ssl/private/sls.key</span></span></code></pre></div><p>Apply the same idea on Protocube if it terminates TLS for its API.</p><h3 id="the-daemon-is-not-connecting-to-protocube" tabindex="-1">The daemon is not connecting to Protocube <a class="header-anchor" href="#the-daemon-is-not-connecting-to-protocube" aria-label="Permalink to &quot;The daemon is not connecting to Protocube&quot;">​</a></h3><p><strong>Ensure the daemon can connect to Protocube:</strong></p><ol><li><p>Check your <strong><code>remote</code></strong> block in the daemon <code>config.yml</code>. The <code>url</code> must point at Protocube, use the correct <strong><code>http</code> or <code>https</code></strong> scheme, and be reachable from wherever the daemon is running (on the host or inside a container):</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">remote</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://protocube.sls.net:5620</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sls_live_your_node_key</span></span></code></pre></div></li><li><p>On the <strong>Protocube</strong> side, confirm the API is listening on the host and port you expect, and that nothing (firewall, security group, etc.) is blocking it.</p></li></ol><p><strong>If you use Docker:</strong> Make sure you are <strong>exposing the right ports</strong> from the container to the host and that port mappings match what you put in your URLs.</p><hr><p>If you are still stuck, ask in the <a href="https://discord.gg/BrH8GtyGSh" target="_blank" rel="noreferrer">Discord</a> <strong>help</strong> channels.</p>`,25)])])}const k=t(o,[["render",a]]);export{g as __pageData,k as default};
